class TFMRegistrationCollectorDateTime extends TFMRegistrationCollector
{
    utcDateTime minimumDate = DateTimeUtil::minValue();
    utcDateTime maximumDate = DateTimeUtil::maxValue();
    str defaultDate = strFmt('%1',DateTimeUtil::Utcnow());


}

